    public static readonly ArenaBoundsCustom Bounds = Create();
    private static ArenaBoundsCustom Create()
    {
        var shapes=Floors.SelectMany(f=>f).Select(p=>(Shape)new PolygonCustom(p.Outer)).ToArray();
        var center=new ArenaBoundsCustom(shapes).Center;
        var layers=Floors.Select((parts,index)=>new ArenaProjectionLayer(new RelSimplifiedComplexPolygon(parts.Select(p=>
        {
            var vertices=p.Outer.Select(v=>v-center).ToList();
            var starts=new List<int>();
            foreach(var hole in p.Holes)
            {
                starts.Add(vertices.Count);
                vertices.AddRange(hole.Select(v=>v-center));
            }
            return new RelPolygonWithHoles(vertices,starts);
        }).ToList()),index<3 ? 95.25f : 90.25f, shared2DGroup: index % 3)).ToArray();
        return new(shapes,WorldProjectionLayers:layers);
    }
